<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cases — Lex Factum</title><link rel="stylesheet" href="<?= base_url('styles.css') ?>"></head><body><div class="crm-wrap"><div class="eyebrow">CRM</div><h1>Cases / Matters</h1><p><a class="crm-btn" href="<?= site_url('admin/crm') ?>">← CRM</a> <a class="crm-btn" href="<?= site_url('admin/crm/cases/create') ?>">+ Add Case</a></p><?php if(session()->getFlashdata('message')): ?><div class="flash"><?= esc(session()->getFlashdata('message')) ?></div><?php endif; ?><table class="crm-table"><tr><th>Case</th><th>Client</th><th>Case No.</th><th>Court</th><th>Status</th><th>Action</th></tr><?php foreach($cases as $c): ?><tr><td><?= esc($c['title']) ?></td><td><?= esc($c['client_name']) ?></td><td><?= esc($c['case_number']) ?></td><td><?= esc($c['court']) ?></td><td><?= esc($c['status']) ?></td><td><a href="<?= site_url('admin/crm/cases/'.$c['id'].'/edit') ?>">Edit</a> · <a href="<?= site_url('admin/crm/cases/'.$c['id'].'/delete') ?>" onclick="return confirm('Delete this case?')">Delete</a></td></tr><?php endforeach; ?></table></div><style>.crm-wrap{max-width:1200px;margin:110px auto;padding:0 24px}.crm-btn{display:inline-block;padding:10px 14px;border:1px solid rgba(180,150,95,.35);border-radius:10px;color:inherit;text-decoration:none}.crm-table{width:100%;border-collapse:collapse}.crm-table th,.crm-table td{padding:12px;border-bottom:1px solid rgba(180,150,95,.18);text-align:left}.flash{padding:12px;background:rgba(180,150,95,.12);margin:15px 0}</style></body></html>
